'use strict';
const DATA=window.SALMON_DATA;
let shiftId=DATA.shifts[0].id;
let series={eggs:true,kills:true,deaths:true};
const seriesColors={eggs:'#d5ef68',kills:'#ff7957',deaths:'#a8b0b4'};
let clearedKillsOnly=false;
const app=document.querySelector('#app');
const esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number.isFinite(n)?n.toLocaleString('zh-CN',{maximumFractionDigits:1}):'—';
const average=(xs,key)=>xs.reduce((s,j)=>s+(j.players[0][key]??0),0)/(xs.length||1);
const date=(s,full=false)=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Hong_Kong',month:'2-digit',day:'2-digit',...(full?{hour:'2-digit',minute:'2-digit',hour12:false}:{})}).format(new Date(s));
const time=s=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Hong_Kong',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(s));
const shift=()=>DATA.shifts.find(s=>s.id===shiftId);
const matches=()=>DATA.jobs.filter(j=>j.shift===shiftId);
const image=(o,cl='',size=32)=>o?.image?`<img class="${cl}" src="${esc(o.image)}" alt="${esc(o.name)}" title="${esc(o.name)}" width="${size}" height="${size}" loading="lazy">`:'';
const weapon=o=>`<span class="weapon-circle" title="${esc(o.name)}">${image(o)}</span>`;
const pill=j=>`<span class="result-group"><span class="result ${j.clear?'':'fail'}">${j.clear?'通过':'WAVE '+j.failedWave+' 失败'}</span>${j.king?`<span class="result-divider">/</span><span class="king-label ${j.king.clear?'king-cleared':''}" title="${j.king.clear?'头目已击倒':'头目未击倒'}">${esc(j.king.name)}<span class="sr-only">（${j.king.clear?'已击倒':'未击倒'}）</span></span>`:''}</span>`;
const stat=(label,value,unit,note,cls='',icon='')=>`<article class="stat-card ${cls}"><div class="stat-label">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}<em>${unit}</em></div><div class="stat-note">${note}</div></article>`;
function overview(){
  const s=shift(),js=matches(),clears=js.filter(j=>j.clear).length,rate=clears/js.length*100;
  const avgE=average(js,'eggs'),avgK=average(js,'kills'),avgD=average(js,'deaths');
  const avgW=js.reduce((n,j)=>n+SalmonStats.passedWaves(j),0)/(js.length||1),killSample=SalmonStats.killAverage(js,clearedKillsOnly);
  document.querySelector('#breadcrumbs').innerHTML='工作台 <span>/</span> 排班总览';
  document.title='排班总览 · 鲑鱼复盘';
  app.innerHTML=`<div class="page-heading"><div><div class="eyebrow">SHIFT REPORT</div><h1>本期打工复盘</h1><p class="subtext">${esc(DATA.player)} 的打工复盘</p></div><select id="shift-select" class="shift-select" aria-label="选择排班">${DATA.shifts.map(x=>`<option value="${x.id}" ${s.id===x.id?'selected':''}>${date(x.start)} — ${date(x.end)} · ${esc(x.stage.name)}</option>`).join('')}</select></div>
  <section class="shift-banner"><div class="shift-copy"><div class="shift-label">${s.id===DATA.shifts[0].id?'最新排班':'历史排班'} / REGULAR <span class="pill ${s.loaded<s.total?'warn':''}">${s.loaded<s.total?'部分记录':'记录完整'} ${s.loaded} / ${s.total}</span></div><div class="shift-title"><h2>${esc(s.stage.name)}</h2><div class="shift-weapons">${s.weapons.map(weapon).join('')}</div></div><div class="shift-meta"><span>${date(s.start,true)} — ${date(s.end,true)}</span><span>危险度 ${fmt(Math.min(...js.map(j=>j.hazard)))}–${fmt(Math.max(...js.map(j=>j.hazard)))}%</span></div></div>${image(s.stage,'shift-art',280)}</section>
  <section class="stat-grid">${stat('本期通过率',fmt(rate),'%',`${clears} 场通过 / ${js.length} 场已记录<br><span class="average-waves" title="常规波次：第 1/2/3 波失败分别通过 0/1/2 波，通过为 3 波；不含 EX-WAVE">平均通过 <strong>${fmt(avgW)}</strong> / 3 波</span>`,'','↗')}${stat('场均搬蛋（个人）',fmt(avgE),'颗',`本期合计 ${fmt(js.reduce((n,j)=>n+j.players[0].eggs,0))} 颗`,'lime','●')}${stat('场均击杀（个人）',fmt(killSample.value),'只',`<div class="kill-scope" role="group" aria-label="场均击杀统计范围"><button data-kill-scope="all" aria-pressed="${!clearedKillsOnly}">全部场次</button><button data-kill-scope="cleared" aria-pressed="${clearedKillsOnly}">仅成功场次</button></div><span class="kill-sample">${killSample.count?'巨大鲑鱼 · '+killSample.count+' 场'+(clearedKillsOnly?'通过':'已记录'):'暂无成功场次'}</span>`,'orange kill-stat','×')}${stat('场均被救援',fmt(avgD),'次',`个人救援合计 ${js.reduce((n,j)=>n+j.players[0].rescues,0)} 次`,'','✚')}</section>
  <section class="analysis-grid"><div class="panel"><div class="panel-head overview-chart-head"><div><h2>个人表现趋势</h2><p class="subtext">按时间从早到晚 · 搬蛋、巨大鲑鱼击杀与被救援</p></div><div class="chart-controls"><button class="legend-button ${series.eggs?'':'off'}" data-series="eggs"><i class="legend-swatch"></i>搬蛋</button><button class="legend-button ${series.kills?'':'off'}" data-series="kills"><i class="legend-swatch kills"></i>击杀</button><button class="legend-button ${series.deaths?'':'off'}" data-series="deaths"><i class="legend-swatch deaths"></i>被救援</button></div></div><div class="chart-wrap" id="chart-wrap">${chart(js)}<div class="tooltip" id="chart-tooltip"></div></div><div class="chart-axis-note"><span>横轴：本期已记录第 x 场</span><button id="expand-chart" class="expand-chart">放大图表 ↗</button></div></div>
  <aside class="panel ai-panel"><div class="ai-title"><h2><span class="spark">✳</span>本期 AI 复盘</h2><span class="demo">演示 · 未接模型</span></div><div class="ai-lead">${avgD>=2?'输出之外，关注生存。':'保持节奏，稳步推进。'}</div><p class="ai-body">这 ${js.length} 场中，你平均搬运 <strong>${fmt(avgE)} 颗</strong>金蛋、击杀 <strong>${fmt(avgK)} 只</strong>巨大鲑鱼。场均被救援 <strong>${fmt(avgD)} 次</strong>，可以优先回看被救援较多的场次。</p><div class="ai-tags"><span>真实统计</span><span>建议仅作示意</span></div><button class="ai-link" data-chat>这期谁杀得最猛？<span>↗</span></button></aside></section>
  <section><div class="section-heading"><h2>本期场次</h2><span class="count-badge">${js.length}</span><span class="subtext">团队数值 <span class="personal">（个人数值）</span> · 最新在前</span></div><div class="panel table-scroll"><table><thead><tr><th>场次 / 结束分数</th><th>结果</th><th>危险度</th><th>搬蛋 <span class="muted">（个人）</span></th><th>击杀 <span class="muted">（个人）</span></th><th>团队红蛋</th><th title="个人被救援次数，不包含未获救的倒地">被救援次数</th><th></th></tr></thead><tbody>${[...js].reverse().map(j=>`<tr class="match-row" data-job="${j.id}" tabindex="0" role="link" aria-label="查看第 ${j.index} 场详情"><td><span class="match-index">#${String(j.index).padStart(2,'0')}</span><span class="match-grade ${j.clear?'grade-cleared':''}" title="${date(j.time,true)} · 结束时的段位分数">${esc(j.grade)} ${fmt(j.gradePoint)}</span></td><td>${pill(j)}</td><td>${fmt(j.hazard)}%</td><td>${j.eggs}<span class="personal">（${j.players[0].eggs}）</span></td><td>${j.kills}<span class="personal kill-personal">（${j.players[0].kills}）</span></td><td>${fmt(j.power)}</td><td>${j.players[0].deaths}</td><td class="row-arrow">↗</td></tr>`).join('')}</tbody></table><div class="table-foot">被救援次数来自 NSO 个人结算，不等同完整倒地次数。击杀指巨大鲑鱼，团队击杀为敌人明细中的团队击倒合计。<br>搬蛋团队数来自各波交蛋合计，个人数来自个人结算；两者可能存在原始数据差异。</div></div>${s.loaded<s.total?`<div class="coverage">本期共 ${s.total} 场，仅保存最近 ${s.loaded} 场；以上统计与问答只覆盖已记录场次，第 x 场为本地记录顺序。</div>`:''}</section>`;
  document.querySelector('#shift-select').onchange=e=>{shiftId=e.target.value;overview()};
  document.querySelectorAll('[data-series]').forEach(b=>b.onclick=()=>{const k=b.dataset.series;if(series[k]&&Object.values(series).filter(Boolean).length===1)return;series[k]=!series[k];overview()});
  document.querySelectorAll('[data-kill-scope]').forEach(b=>b.onclick=()=>{clearedKillsOnly=b.dataset.killScope==='cleared';overview()});
  document.querySelector('#expand-chart').onclick=openTrend;
  wireCommon();wireChart(js);
  const smallChart=document.querySelector('#chart-wrap svg');smallChart.onclick=openTrend;smallChart.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openTrend()}};
}
function chart(js){
  const W=window.innerWidth<720?Math.max(270,window.innerWidth-66):760,H=245,L=36,R=17,T=20,B=31,max=Math.max(10,Math.ceil(Math.max(...js.flatMap(j=>[series.eggs?j.players[0].eggs:0,series.kills?j.players[0].kills:0,series.deaths?j.players[0].deaths:0]))/10)*10);
  const x=i=>L+i*(W-L-R)/Math.max(1,js.length-1),y=v=>H-B-v/max*(H-B-T);
  const coords=key=>js.map((j,i)=>`${x(i)},${y(j.players[0][key])}`).join(' ');
  return `<svg viewBox="0 0 ${W} ${H}" role="button" tabindex="0" aria-haspopup="dialog" aria-label="放大个人搬蛋、巨大鲑鱼击杀与被救援折线图"><defs><linearGradient id="egg-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#d5ef68" stop-opacity=".13"/><stop offset="100%" stop-color="#d5ef68" stop-opacity="0"/></linearGradient></defs>${Array.from({length:6},(_,i)=>{const v=max*i/5;return `<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" class="chart-grid"/><text class="chart-text" x="${L-11}" y="${y(v)+4}" text-anchor="end">${fmt(v)}</text>`}).join('')}${series.eggs?`<polygon points="${L},${H-B} ${coords('eggs')} ${x(js.length-1)},${H-B}" fill="url(#egg-fill)"/>`:''}${['eggs','kills','deaths'].filter(k=>series[k]).map(k=>`<polyline class="chart-line" stroke="${seriesColors[k]}" points="${coords(k)}"/>${js.map((j,i)=>`<circle class="chart-point ${j.clear?'node-cleared':'node-failed'}" cx="${x(i)}" cy="${y(j.players[0][k])}" r="3.5" fill="${j.clear?(seriesColors[k]):'var(--panel)'}" stroke="${seriesColors[k]}" stroke-width="1.6"/>`).join('')}`).join('')}${js.map((j,i)=>`<rect class="chart-hit" data-chart-job="${j.id}" x="${x(i)-Math.min(24,(W-L-R)/Math.max(1,js.length-1))/2}" y="${T}" width="${Math.min(24,(W-L-R)/Math.max(1,js.length-1))}" height="${H-B-T}" aria-label="第 ${j.index} 场，搬蛋 ${j.players[0].eggs}，击杀 ${j.players[0].kills}，被救援 ${j.players[0].deaths}"/>${i===0||i===js.length-1||(i+1)%(W<500?5:3)===0?`<text class="chart-text" x="${x(i)}" y="${H-8}" text-anchor="middle">${j.index}</text>`:''}`).join('')}</svg>`;
}
function wireChart(js){const tt=document.querySelector('#chart-tooltip'),wrap=document.querySelector('#chart-wrap');document.querySelectorAll('[data-chart-job]').forEach(e=>{e.onpointermove=ev=>{const j=js.find(j=>j.id===e.dataset.chartJob),r=wrap.getBoundingClientRect();tt.innerHTML=`第 ${j.index} 场 · ${j.clear?'通过':'失败'}<br><span style="color:var(--lime)">搬蛋 ${j.players[0].eggs}<span class="tip-assist"> + ${fmt(j.players[0].assist)} 协助</span></span>　<span style="color:var(--orange)">击杀 ${j.players[0].kills}</span><br><span style="color:${seriesColors.deaths}">被救援 ${j.players[0].deaths} 次</span>`;tt.style.display='block';tt.style.left=Math.max(5,Math.min(ev.clientX-r.left+12,r.width-tt.offsetWidth-6))+'px';tt.style.top='12px'};e.onpointerleave=()=>tt.style.display='none';e.onclick=ev=>{ev.stopPropagation();openTrend()};e.onkeydown=ev=>{if(ev.key==='Enter'){ev.stopPropagation();openTrend()}}})}
function wireCommon(){document.querySelectorAll('[data-job]').forEach(el=>{el.onclick=()=>location.hash=el.dataset.job;el.onkeydown=e=>{if(e.key==='Enter')location.hash=el.dataset.job}});document.querySelectorAll('[data-chat]').forEach(b=>b.onclick=openChat)}
function unusedSpecialTag(j,p){
  const usage=SalmonStats.unusedSpecials(j,p);
  return usage?`<span class="unused-special-tag" title="本场失败；常规波次已用 ${usage.used}/2 次大招，剩余 ${usage.remaining} 次">裤裆藏大</span>`:'';
}
function detail(j){
  const js=matches(),pos=js.findIndex(x=>x.id===j.id),me=j.players[0],teamBosses=j.bosses.reduce((n,b)=>n+b.team,0),spawned=j.bosses.reduce((n,b)=>n+b.appeared,0);
  document.title=`第 ${j.index} 场 · 鲑鱼复盘`;
  document.querySelector('#breadcrumbs').innerHTML=`工作台 <span>/</span> <a href="#">排班总览</a> <span>/</span> 第 ${j.index} 场`;
  app.innerHTML=`<div class="detail-toolbar"><a href="#" class="back-link">← 返回排班总览</a><div class="pager">${pos>0?`<a class="button" href="#${js[pos-1].id}">← 上一场</a>`:'<button class="button" disabled>← 上一场</button>'}<span>${pos+1} / ${js.length}</span>${pos<js.length-1?`<a class="button" href="#${js[pos+1].id}">下一场 →</a>`:'<button class="button" disabled>下一场 →</button>'}</div></div>
  <section class="job-banner panel"><div class="job-banner-copy"><div class="eyebrow">JOB REPORT / #${String(j.index).padStart(2,'0')}</div><div class="job-title"><h1>${esc(j.stage.name)}</h1>${pill(j)}</div><p class="subtext">${date(j.time,true)} · 危险度 <strong>${fmt(j.hazard)}%</strong> · ${esc(j.grade)} ${fmt(j.gradePoint)}</p></div>${image(j.stage,'job-art',250)}</section>
  <section class="stat-grid">${stat('搬蛋 · 团队 / 个人',`${j.eggs}<span class="small-personal">（${me.eggs}）</span>`,'颗','个人搬蛋不含协助搬运','lime')}${stat('击杀 · 团队 / 个人',`${j.kills}<span class="small-personal">（${me.kills}）</span>`,'只','巨大鲑鱼明细 · 团队击倒合计','orange')}${stat('红蛋 · 团队',fmt(j.power),'颗',`个人 ${fmt(me.power)} 颗`)}${stat('个人救援 / 被救援',`${me.rescues} <span class="slash">/</span> ${me.deaths}`,'次','被救援不等同完整倒地次数')}</section>
  <div class="detail-layout"><div class="detail-main"><section class="panel"><div class="panel-head"><h2>波次表现</h2><span class="subtext">潮位 / 事件 / 交蛋</span></div><div class="waves">${j.waves.map(w=>{const ex=w.number>3,passed=ex?j.king?.clear:(j.clear||w.number<j.failedWave);return `<article class="wave-card ${ex?'ex-wave':''}"><div class="wave-heading"><h3>${ex?'EX-WAVE':'WAVE '+w.number}</h3><span class="${passed?'wave-ok':'muted'}">${passed?'✓':'—'}</span></div><div class="wave-score">${ex?(j.king?.clear?'击倒！':'未击倒'):`${w.eggs}<small> / ${w.quota}</small>`}</div><div class="wave-meta"><span>${esc(w.tide)}</span><span>${esc(ex?j.king?.name:w.event)}</span></div><div class="wave-spawn">金蛋出现 ${w.appeared} 颗</div><div class="wave-specials">${w.specials.length?w.specials.map(s=>image(s,'',26)).join(''):'<span>未使用特殊武器</span>'}</div></article>`}).join('')}</div></section>
  <section><div class="section-heading"><h2>队员表现</h2><span class="subtext">武器按波次排列</span></div><div class="panel table-scroll"><table class="players-table"><thead><tr><th>队员 / 武器</th><th>巨大鲑鱼</th><th>搬蛋 <span class="muted">+ 协助</span></th><th>红蛋</th><th>救援 / 被救援</th></tr></thead><tbody>${j.players.map(p=>`<tr class="${p.me?'my-row':''}"><td><div class="player-name">${esc(p.name)} ${p.me?'<span class="you-tag">YOU</span>':''} ${unusedSpecialTag(j,p)}</div><div class="player-weapons">${p.weapons.map((w,i)=>`<span title="${i<3?'WAVE '+(i+1):'EX-WAVE'} · ${esc(w.name)}">${image(w,'',29)}</span>`).join('')}<i></i>${image(p.special,'',25)}</div></td><td class="kill-number">${p.kills}</td><td><strong class="egg-number">${p.eggs}</strong> <span class="assist">+ ${p.assist}</span></td><td>${fmt(p.power)}</td><td>${p.rescues} <span class="muted">/</span> ${p.deaths}</td></tr>`).join('')}</tbody></table></div>${j.eggReconciliationDelta?`<p class="page-footer-note">本场个人搬蛋之和与波次交蛋之和相差 ${j.eggReconciliationDelta} 颗，按原始字段分别展示。</p>`:''}</section>
  <section class="panel"><div class="panel-head"><div><h2>巨大鲑鱼明细</h2><p class="subtext">团队击倒 <span class="personal">（个人）</span> / 出现数量</p></div><span class="boss-total">${teamBosses}<small> / ${spawned}</small></span></div><div class="boss-grid">${j.bosses.map(b=>`<div class="boss-item">${image(b,'boss-icon',46)}<div class="boss-info"><div class="boss-line"><span>${esc(b.name)}</span><span>${b.team}<b>（${b.me}）</b><em> / ${b.appeared}</em></span></div><div class="boss-bar"><span style="width:${Math.min(100,b.team/Math.max(1,b.appeared)*100)}%"></span></div></div></div>`).join('')}</div><div class="table-foot">团队击倒 ${j.kills} 只；四名队员个人击杀合计 ${j.playerKills} 只。两种原始统计口径可能不同，总览采用此处团队击倒数。</div></section>
  ${j.king?`<section class="panel king-panel">${image(j.king,'king-image',105)}<div><div class="eyebrow">KING SALMONID</div><h2>${esc(j.king.name)} <span class="result ${j.king.clear?'':'fail'}">${j.king.clear?'成功击倒':'未击倒'}</span></h2><p class="subtext">${j.scales?`获得鳞片：<span class="gold">金 ${j.scales.gold}</span> · 银 ${j.scales.silver} · 铜 ${j.scales.bronze}`:'未记录鳞片奖励'}</p></div></section>`:''}
  </div><aside class="detail-aside"><section class="panel ai-panel"><div class="ai-title"><h2><span class="spark">✳</span>本场 AI 建议</h2><span class="demo">演示 · 未接模型</span></div><div class="ai-lead">${me.deaths>=3?'这场值得回看生存节奏。':me.eggs>=average(js,'eggs')?'搬蛋高于本期个人场均。':'结合波次，回看分工。'}</div><p class="ai-body">本场搬蛋 <strong>${me.eggs} 颗</strong>，本期场均 <strong>${fmt(average(js,'eggs'))}</strong>；击杀 <strong>${me.kills} 只</strong>，本期场均 <strong>${fmt(average(js,'kills'))}</strong>。</p><div class="review-note"><span>可复盘的方向</span><p>${me.deaths>=3?`被救援 ${me.deaths} 次。建议结合录像检查倒地时的位置、撤退路线与特殊武器使用时机。`:'结合各波武器与潮位，检查远端击杀和篮筐附近搬蛋的时间分配。'}</p></div><p class="ai-disclaimer">以上为模板建议。仅凭结算数据无法判断具体倒地原因、走位或队伍分工。</p><button class="ai-link" data-chat>打开本期问答<span>↗</span></button></section>
  <section class="panel reward-panel"><div class="eyebrow">GRIZZCO POINTS</div><h2>获得点数</h2><div class="reward-value">${fmt(j.jobPoint)}<small>p</small></div><div class="reward-equation">${fmt(j.jobScore)} × ${esc(j.jobRate)} + ${fmt(j.jobBonus)}</div><div class="reward-labels"><span>打工分数</span><span>评价倍率</span><span>过关奖励</span></div></section><p class="page-footer-note">数据来自 NSO 结算记录<br>时间统一为 UTC+8</p></aside></div>`;
  wireCommon();
}
function answerQuestion(q){
  const js=matches(),s=shift(),refs=items=>`<div class="evidence-links">${items.map(j=>`<a href="#${j.id}" data-evidence>第 ${j.index} 场 ↗</a>`).join('')}</div>`;
  const scope=`仅统计本期已记录 ${js.length} / ${s.total} 场。`;
  if(/杀|擊|击|猛|排行|排名/.test(q)){
    const totals=new Map();js.forEach(j=>j.players.forEach(p=>{const a=totals.get(p.key)||{name:p.name,kills:0,n:0};a.kills+=p.kills;a.n++;totals.set(p.key,a)}));
    const ranked=[...totals.values()].sort((a,b)=>b.kills-a.kills),top=ranked[0];
    const topJobs=[...js].sort((a,b)=>Math.max(...b.players.map(p=>p.kills))-Math.max(...a.players.map(p=>p.kills))).slice(0,3);
    return `<p>按<strong>累计巨大鲑鱼击杀</strong>，<strong>${esc(top.name)}</strong> 最高，共 <strong>${top.kills} 只</strong>。</p><div class="ranking">${ranked.slice(0,5).map((p,i)=>`<div><span>${i+1}. ${esc(p.name)}</span><strong>${p.kills}</strong><small>${p.n} 场 · 场均 ${fmt(p.kills/p.n)}</small></div>`).join('')}</div><p class="subtext">${scope} 队员参场数不同，累计排名不代表同等样本下的水平比较。以下是单场最高击杀较高的记录：</p>${refs(topJobs)}`;
  }
  if(/蛋|搬|运|運/.test(q)){
    const sorted=[...js].sort((a,b)=>b.players[0].eggs-a.players[0].eggs),sum=js.reduce((n,j)=>n+j.players[0].eggs,0);
    return `<p>你累计搬运 <strong>${sum} 颗</strong>金蛋，场均 <strong>${fmt(average(js,'eggs'))} 颗</strong>。最高为第 ${sorted[0].index} 场的 <strong>${sorted[0].players[0].eggs} 颗</strong>。</p><p class="subtext">${scope} 统计包含失败场次，不含协助搬运；不同波数与事件会影响场均，不能直接归因为个人能力。</p>${refs(sorted.slice(0,3))}`;
  }
  if(/复盘|復盤|死|救|短板|建议|建議|哪|失败/.test(q)){
    const selected=[...js].sort((a,b)=>b.players[0].deaths-a.players[0].deaths||a.clear-b.clear).slice(0,3);
    return `<p>可以先回看以下被救援次数较多的场次：</p><ul>${selected.map(j=>`<li>第 ${j.index} 场：被救援 ${j.players[0].deaths} 次，搬蛋 ${j.players[0].eggs}，击杀 ${j.players[0].kills}，${j.clear?'通过':'第 '+j.failedWave+' 波失败'}。</li>`).join('')}</ul><p class="subtext">${scope} 这是复盘入口，不是失误判定；原因需结合录像、武器与事件确认。</p>${refs(selected)}`;
  }
  return '<p>当前是本地规则问答演示，支持击杀排行、个人搬蛋统计和复盘场次查询，尚未接入大模型。</p><p class="subtext">试试「这期谁杀得最猛？」或「我的搬蛋表现怎么样？」。</p>';
}
function openChat(){
  const d=document.querySelector('#chat-dialog');
  document.querySelector('#chat-content').innerHTML=`<div class="chat-header"><div><div class="eyebrow">SALMON ASSISTANT / DEMO</div><h2 id="chat-title">打工助手</h2></div><button class="close-chat" id="close-chat" aria-label="关闭问答">×</button></div><div class="chat-scope"><span class="status-dot"></span>${esc(shift().stage.name)} · 本期 ${matches().length} 场记录</div><div class="chat-messages" id="chat-messages" aria-live="polite"><div class="chat-message assistant"><span class="message-label">助手 · 规则演示</span><p>想从哪一场开始复盘？这里可以查询本期真实数据，回答会附上可打开的场次。</p><p class="subtext">目前使用本地规则，不会调用大模型。</p></div></div><div class="chat-suggestions">${['这期谁杀得最猛？','我的搬蛋表现怎么样？','哪些场次值得复盘？'].map(q=>`<button type="button" data-question="${q}">${q}</button>`).join('')}</div><form id="chat-form"><label class="sr-only" for="chat-input">输入打工问题</label><input id="chat-input" maxlength="300" placeholder="询问本期表现…" autocomplete="off" required><button class="button primary" type="submit" aria-label="发送问题">↑</button></form><p class="chat-footer">本地查询 · 不发送数据 · AI 接口预留</p>`;
  document.querySelector('#close-chat').onclick=()=>d.close();
  const ask=q=>{q=q.trim();if(!q)return;const list=document.querySelector('#chat-messages');list.insertAdjacentHTML('beforeend',`<div class="chat-message user"><span class="message-label">你</span><p>${esc(q)}</p></div><div class="chat-message assistant"><span class="message-label">助手 · 规则演示</span>${answerQuestion(q)}</div>`);document.querySelector('#chat-input').value='';list.scrollTop=list.scrollHeight;list.querySelectorAll('[data-evidence]').forEach(a=>a.onclick=()=>d.close())};
  document.querySelector('#chat-form').onsubmit=e=>{e.preventDefault();ask(document.querySelector('#chat-input').value)};
  document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));
  d.onclick=e=>{if(e.target===d)d.close()};
  if(!d.open)d.showModal();
}
function route(){const id=location.hash.slice(1),j=DATA.jobs.find(j=>j.id===id);document.querySelector('#nav-overview').classList.toggle('active',!j);document.querySelector('#nav-latest').classList.toggle('active',!!j);if(j){shiftId=j.shift;detail(j)}else overview();window.scrollTo(0,0)}
document.querySelector('.sidebar-bottom>p').innerHTML=`${DATA.jobs.length} 场记录 · ${DATA.shifts.length} 期排班<br>更新于 ${date(DATA.generated)}`;
document.querySelector('.profile>div:last-child').innerHTML=`${esc(DATA.player)}<small>我的打工记录</small>`;
document.querySelector('#nav-latest').onclick=()=>location.hash=matches().at(-1).id;
document.querySelector('#nav-chat').onclick=openChat;
window.addEventListener('hashchange',route);route();
let resizeTimer;
window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(!DATA.jobs.some(j=>'#'+j.id===location.hash))overview()},120)});
